+inline HashPrefix CreateKeyPrefix(const SipHasher13UJ& hasher, const uint256& script_hash)
+{
+    return hasher.Hash(script_hash) >> (8 * (sizeof(HashPrefix) - HASH_PREFIX_SIZE));
